using System;
using Fusion;
using UnityEngine;
using UnityEngine.VFX;

public class Ammo : NetworkBehaviour
{
    public LayerMask collisionMask;

    public float speed;
    public float projectileDis = 3f;
    public Transform weaponTransform;

    public ParticleSystem projectileParticles;
    public VisualEffect projectileVisualEffect;

    [Networked] private Vector3 MoveDirection { get; set; }
    [Networked] private float DamageValue { get; set; }
    [Networked] private float MoveSpeed { get; set; }
    [Networked] private float MaxDistance { get; set; }
    [Networked] private Vector3 SpawnPosition { get; set; }
    [Networked] private Vector3 SyncedPosition { get; set; }
    [Networked] private Quaternion SyncedRotation { get; set; }
    [Networked] private NetworkBool IsInitialized { get; set; }

    public void Initialize(Vector3 spawnPosition, Vector3 direction, float damageValue, float moveSpeed, float maxDistance)
    {
        SpawnPosition = spawnPosition;
        MoveDirection = direction.sqrMagnitude > 0.0001f ? direction.normalized : transform.forward;
        DamageValue = damageValue;
        MoveSpeed = moveSpeed;
        MaxDistance = maxDistance;
        SyncedPosition = spawnPosition;
        SyncedRotation = Quaternion.LookRotation(MoveDirection);
        transform.SetPositionAndRotation(SyncedPosition, SyncedRotation);
        IsInitialized = true;
    }

    public void SetDamage(float damage)
    {
        DamageValue = damage;
    }

    public void SetLookDirection(Vector3 lookDirection)
    {
        MoveDirection = lookDirection.sqrMagnitude > 0.0001f ? lookDirection.normalized : transform.forward;
    }


    public override void FixedUpdateNetwork()
    {
        if (IsInitialized == false)
            return;

        float moveDistance = MoveSpeed * Runner.DeltaTime;
        transform.position += MoveDirection * moveDistance;

        if (HasStateAuthority == false)
            return;

        CheckCollisions(moveDistance);

        if (Vector3.Distance(transform.position, SpawnPosition) > MaxDistance)
        {
            Runner.Despawn(Object);
        }
    }

    private void CheckCollisions(float moveDistance)
    {
        Ray ray = new Ray(transform.position, MoveDirection);
        RaycastHit hit;
        if (Physics.Raycast(ray, out hit, moveDistance, collisionMask, QueryTriggerInteraction.Collide))
        {
            OnHitObject(hit);
        }
    }

    private void OnHitObject(RaycastHit hit)
    {
        if (HasStateAuthority == false)
            return;

        IDamageable damageableObject = hit.collider.GetComponent<IDamageable>();
        if (damageableObject != null)
        {
            damageableObject.TakeHit(DamageValue, hit); // 데미지 입히기
        }
        Runner.Despawn(Object);
    }

    // // 트리거 충돌 감지
    // private void OnCollisionEnter(Collision other)
    // {
    //     if (!HasStateAuthority) return;
    //     
    //     ContactPoint contatPoint = other.contacts[0];
    //     Vector2 hitPoint = contatPoint.point;
    //     
    //     // if (other.gameObject.TryGetComponent<Enemy>(out var enemy))
    //     // {
    //     //     if(projectileParticles != null)
    //     //     {
    //     //         projectileParticles.transform.position = hitPoint;
    //     //         projectileParticles.Play();
    //     //     }
    //     //     else if(projectileVisualEffect != null)
    //     //     {
    //     //         projectileVisualEffect.transform.position = hitPoint;
    //     //         projectileVisualEffect.Play();
    //     //     }
    //     //     enemyTakeDamage(10f); // 데미지 입히기
    //     //     Runner.Despawn(Object); // 충돌 후 총알 삭제
    //     // }
    // }
}

using System;
using Fusion;
using UnityEngine;
using UnityEngine.VFX;

public class Ammo : NetworkBehaviour
{
    public LayerMask collisionMask;

    public float speed;
    public float projectileDis = 3f;
    public Transform weaponTransform;

    public ParticleSystem projectileParticles;
    public VisualEffect projectileVisualEffect;

    [Networked] private Vector3 MoveDirection { get; set; }
    [Networked] private float DamageValue { get; set; }
    [Networked] private float MoveSpeed { get; set; }
    [Networked] private float MaxDistance { get; set; }
    [Networked] private Vector3 SpawnPosition { get; set; }
    [Networked] private Vector3 SyncedPosition { get; set; }
    [Networked] private Quaternion SyncedRotation { get; set; }
    [Networked] private NetworkBool IsInitialized { get; set; }

    public void Initialize(Vector3 spawnPosition, Vector3 direction, float damageValue, float moveSpeed, float maxDistance)
    {
        SpawnPosition = spawnPosition;
        MoveDirection = direction.sqrMagnitude > 0.0001f ? direction.normalized : transform.forward;
        DamageValue = damageValue;
        MoveSpeed = moveSpeed;
        MaxDistance = maxDistance;
        SyncedPosition = spawnPosition;
        SyncedRotation = Quaternion.LookRotation(MoveDirection);
        transform.SetPositionAndRotation(SyncedPosition, SyncedRotation);
        IsInitialized = true;
    }

    public void SetDamage(float damage)
    {
        DamageValue = damage;
    }

    public void SetLookDirection(Vector3 lookDirection)
    {
        MoveDirection = lookDirection.sqrMagnitude > 0.0001f ? lookDirection.normalized : transform.forward;
    }


    public override void FixedUpdateNetwork()
    {
        if (IsInitialized == false)
            return;

        if (HasStateAuthority)
        {
            float moveDistance = MoveSpeed * Runner.DeltaTime;
            transform.position += MoveDirection * moveDistance;
            if (MoveDirection.sqrMagnitude > 0.0001f)
            {
                transform.rotation = Quaternion.LookRotation(MoveDirection);
            }

            SyncedPosition = transform.position;
            SyncedRotation = transform.rotation;

            CheckCollisions(moveDistance);

            if (Vector3.Distance(transform.position, SpawnPosition) > MaxDistance)
            {
                Runner.Despawn(Object);
            }
            return;
        }

        // 프록시 클라이언트: 동기화된 위치/회전 적용
        transform.SetPositionAndRotation(SyncedPosition, SyncedRotation);
    }

    private void CheckCollisions(float moveDistance)
    {
        Ray ray = new Ray(transform.position, MoveDirection);
        RaycastHit hit;
        if (Physics.Raycast(ray, out hit, moveDistance, collisionMask, QueryTriggerInteraction.Collide))
        {
            OnHitObject(hit);
        }
    }

    private void OnHitObject(RaycastHit hit)
    {
        if (HasStateAuthority == false)
            return;

        IDamageable damageableObject = hit.collider.GetComponent<IDamageable>();
        if (damageableObject != null)
        {
            damageableObject.TakeHit(DamageValue, hit); // 데미지 입히기
        }
        Runner.Despawn(Object);
    }

    // // 트리거 충돌 감지
    // private void OnCollisionEnter(Collision other)
    // {
    //     if (!HasStateAuthority) return;
    //     
    //     ContactPoint contatPoint = other.contacts[0];
    //     Vector2 hitPoint = contatPoint.point;
    //     
    //     // if (other.gameObject.TryGetComponent<Enemy>(out var enemy))
    //     // {
    //     //     if(projectileParticles != null)
    //     //     {
    //     //         projectileParticles.transform.position = hitPoint;
    //     //         projectileParticles.Play();
    //     //     }
    //     //     else if(projectileVisualEffect != null)
    //     //     {
    //     //         projectileVisualEffect.transform.position = hitPoint;
    //     //         projectileVisualEffect.Play();
    //     //     }
    //     //     enemyTakeDamage(10f); // 데미지 입히기
    //     //     Runner.Despawn(Object); // 충돌 후 총알 삭제
    //     // }
    // }
}

using UnityEngine;
using Fusion;
using Fusion.Addons.Physics;

namespace Projectiles.NetworkObjectExample
{
	// PhysicsProjectile is a NetworkObject spawned in a scene. It uses NetworkRigidbody to synchronize
	// its position and rotation constantly to all clients. This is inefficient and should really be used only
	// for special scenarios (e.g. large rolling projectile that needs to use Rigidbody) or when simplicity is the key.
	// See Projectiles Advanced how even grenades can be done without spawning separate NetworkObjects.
	// For a simple projectile example jump directly to the Example 3.
	[RequireComponent(typeof(NetworkRigidbody3D))]
	public class PhysicsProjectile : NetworkBehaviour
	{
		// PRIVATE MEMBERS

		[SerializeField]
		private float _initialImpulse = 100f;
		[SerializeField]
		private float _lifeTime = 4f;
		[SerializeField]
		private GameObject _visualsRoot;
		[SerializeField]
		private GameObject _hitEffect;
		[SerializeField]
		private float _lifeTimeAfterHit = 2f;

		[Networked]
		private TickTimer _lifeCooldown { get; set; }
		[Networked]
		private NetworkBool _isDestroyed { get; set; }

		private bool _isDestroyedRender;

		private NetworkRigidbody3D _rigidbody;
		private Collider _collider;

		// PUBLIC METHODS

		public void Fire(Vector3 position, Quaternion rotation)
		{
			// TODO: Is teleport still necessary?
			_rigidbody.Teleport(position, rotation);

			_rigidbody.Rigidbody.isKinematic = false;
			_rigidbody.Rigidbody.AddForce(transform.forward * _initialImpulse, ForceMode.Impulse);

			// Set cooldown after which the projectile should be despawned
			if (_lifeTime > 0f)
			{
				_lifeCooldown = TickTimer.CreateFromSeconds(Runner, _lifeTime);
			}
		}

		// NetworkBehaviour INTERFACE

		public override void FixedUpdateNetwork()
		{
			_collider.enabled = _isDestroyed == false;

			if (_lifeCooldown.IsRunning == true && _lifeCooldown.Expired(Runner) == true)
			{
				Runner.Despawn(Object);
			}
		}

		public override void Render()
		{
			if (_isDestroyed == true && _isDestroyedRender == false)
			{
				_isDestroyedRender = true;
				ShowDestroyEffect();
			}
		}

		// MONOBEHAVIOUR

		protected void Awake()
		{
			_rigidbody = GetComponent<NetworkRigidbody3D>();
			_collider = GetComponentInChildren<Collider>();

			_collider.enabled = false;

			if (_hitEffect != null)
			{
				_hitEffect.SetActive(false);
			}
		}

		protected void OnCollisionEnter(Collision collision)
		{
			if (collision.rigidbody != null && Object != null)
			{
				ProcessHit();
			}
		}

		// PRIVATE METHODS

		private void ProcessHit()
		{
			// Save destroyed flag so hit effects can be shown on other clients as well
			_isDestroyed = true;

			_lifeCooldown = TickTimer.CreateFromSeconds(Runner, _lifeTimeAfterHit);

			// Stop the movement
			_rigidbody.Rigidbody.isKinematic = true;
			_collider.enabled = false;
		}

		private void ShowDestroyEffect()
		{
			if (_hitEffect != null)
			{
				_hitEffect.SetActive(true);
			}

			// Hide projectile visual
			if (_visualsRoot != null)
			{
				_visualsRoot.SetActive(false);
			}
		}
	}
}

using UnityEngine;
using Fusion;
using Fusion.Addons.Physics;

namespace Projectiles.NetworkObjectExample
{
	// PhysicsProjectile is a NetworkObject spawned in a scene. It uses NetworkRigidbody to synchronize
	// its position and rotation constantly to all clients. This is inefficient and should really be used only
	// for special scenarios (e.g. large rolling projectile that needs to use Rigidbody) or when simplicity is the key.
	// See Projectiles Advanced how even grenades can be done without spawning separate NetworkObjects.
	// For a simple projectile example jump directly to the Example 3.
	[RequireComponent(typeof(NetworkRigidbody3D))]
	public class PhysicsProjectile : NetworkBehaviour
	{
		// PRIVATE MEMBERS

		[SerializeField]
		private float _initialImpulse = 100f;
		[SerializeField]
		private float _lifeTime = 4f;
		[SerializeField]
		private GameObject _visualsRoot;
		[SerializeField]
		private GameObject _hitEffect;
		[SerializeField]
		private float _lifeTimeAfterHit = 2f;

		[Networked]
		private TickTimer _lifeCooldown { get; set; }
		[Networked]
		private NetworkBool _isDestroyed { get; set; }

		private bool _isDestroyedRender;

		private NetworkRigidbody3D _rigidbody;
		private Collider _collider;

		// PUBLIC METHODS

		public void Fire(Vector3 position, Quaternion rotation)
		{
			// ✅ null 체크 추가
			if (_rigidbody == null)
			{
				_rigidbody = GetComponent<NetworkRigidbody3D>();
			}

			if (_rigidbody == null || _rigidbody.Rigidbody == null || Runner == null)
			{
				Debug.LogError("[PhysicsProjectile] Cannot fire - _rigidbody, Rigidbody, or Runner is null!");
				return;
			}

			// 이제 안전하게 호출
			_rigidbody.Teleport(position, rotation);

			_rigidbody.Rigidbody.isKinematic = false;
			_rigidbody.Rigidbody.AddForce(transform.forward * _initialImpulse, ForceMode.Impulse);

			// Set cooldown after which the projectile should be despawned
			if (_lifeTime > 0f)
			{
				_lifeCooldown = TickTimer.CreateFromSeconds(Runner, _lifeTime);
			}
		}

		// NetworkBehaviour INTERFACE

		public override void FixedUpdateNetwork()
		{
			_collider.enabled = _isDestroyed == false;

			if (_lifeCooldown.IsRunning == true && _lifeCooldown.Expired(Runner) == true)
			{
				Runner.Despawn(Object);
			}
		}

		public override void Render()
		{
			if (_isDestroyed == true && _isDestroyedRender == false)
			{
				_isDestroyedRender = true;
				ShowDestroyEffect();
			}
		}

		// MONOBEHAVIOUR

		protected void Awake()
		{
			_rigidbody = GetComponent<NetworkRigidbody3D>();
			_collider = GetComponentInChildren<Collider>();

			_collider.enabled = false;

			if (_hitEffect != null)
			{
				_hitEffect.SetActive(false);
			}
		}

		protected void OnCollisionEnter(Collision collision)
		{
			if (collision.rigidbody != null && Object != null)
			{
				ProcessHit();
			}
		}

		// PRIVATE METHODS

		private void ProcessHit()
		{
			// Save destroyed flag so hit effects can be shown on other clients as well
			_isDestroyed = true;

			_lifeCooldown = TickTimer.CreateFromSeconds(Runner, _lifeTimeAfterHit);

			// Stop the movement
			_rigidbody.Rigidbody.isKinematic = true;
			_collider.enabled = false;
		}

		private void ShowDestroyEffect()
		{
			if (_hitEffect != null)
			{
				_hitEffect.SetActive(true);
			}

			// Hide projectile visual
			if (_visualsRoot != null)
			{
				_visualsRoot.SetActive(false);
			}
		}
	}
}

using System.Collections;
using Fusion;
using UnityEngine;

namespace Projectiles.NetworkObjectExample
{
    public class Weapon_NetworkObject : WeaponBase
    {
        // PRIVATE MEMBERS

        [SerializeField] private PhysicsProjectile _projectilePrefab;

        [SerializeField,
         Tooltip(
             "NetworkObjectBuffer will pre-spawn projectiles in advance to mitigate spawn delay on input authority")]
        private bool _useBuffer;

        [SerializeField] private NetworkObjectBuffer _projectileBuffer;

        [Networked] private int _fireCount { get; set; }

        public WeaponScriptableObject WeaponSO;

        private int _visibleFireCount;

        private Transform originParent;

        private float damage;
        private float criticalDamage;
        public LayerMask raycastLayerMask;

        // WeaponBase INTERFACE

        public override void Fire(float damage, float criticalDamage)
        {
            this.damage = damage;
            this.criticalDamage = criticalDamage;
            switch (WeaponSO.weaponType)
            {
                case WeaponType.Projectile:
                    if (_useBuffer == true)
                    {
                        FireWithBuffer();
                    }
                    else
                    {
                        FireSimple();
                    }

                    _fireCount++;
                    break;
                case WeaponType.Laser:
                    StartCoroutine(FireLaser());
                    break;
                case WeaponType.Area:
                    StartCoroutine(AreaAttack());
                    break;
                case WeaponType.Strike:
                    break;
            }
        }

        public override void Spawned()
        {
            // In case of late join (and other scenarios) this object can be spawned
            // with fire count larger than zero. To prevent unwanted fire effects triggered in Render method
            // we consider all fire that happened before the Spawn as already visible.
            _visibleFireCount = _fireCount;
            originParent = transform.parent;
        }

        public override void Render()
        {
            if (_visibleFireCount < _fireCount)
            {
                // WeaponSO null 체크 추가
                if (WeaponSO != null)
                {
                    // PlayFireEffect(); // 사운드 재생
                    switch (WeaponSO.weaponType)
                    {
                        case WeaponType.Laser:
                            StartCoroutine(FireLaserVisuals());
                            break;
                        case WeaponType.Area:
                            StartCoroutine(AreaAttackVisuals());
                            break;
                        case WeaponType.Projectile:
                            break;
                    }
                }
            }

            _visibleFireCount = _fireCount;
        }

        // PRIVATE METHODS

        private void FireSimple()
        {
            // Spawn can be called only on state authority
            if (HasStateAuthority == false)
                return;

            var projectile = Runner.Spawn(_projectilePrefab, FireTransform.position, FireTransform.rotation,
                Object.InputAuthority);
            projectile.Fire(FireTransform.position, FireTransform.rotation, damage + WeaponSO.weaponDamage, raycastLayerMask);
        }

        private void FireWithBuffer()
        {
            // In Fusion 2 there is no longer a predicted spawn. We can go around this to have a buffer of pre-spawned
            // objects that are already living inside simulation but inactive. Check NetworkObjectBuffer component for more info.
            var projectile = _projectileBuffer.Get<PhysicsProjectile>(FireTransform.position, FireTransform.rotation,
                Object.InputAuthority);
            if (projectile != null)
            {
                projectile.Fire(FireTransform.position, FireTransform.rotation, damage + WeaponSO.weaponDamage, raycastLayerMask);
            }
        }

        private IEnumerator AreaAttack()
        {
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            Plane groundPlane = new Plane(Vector3.up, transform.root.position);
            Vector3 mouseWorldPos = Vector3.zero;
            if (groundPlane.Raycast(ray, out float distance))
            {
                mouseWorldPos = ray.GetPoint(distance);
            }

            //  네트워크 버퍼에 타겟 위치 저장 (Laser/Area 동기화를 위해)
            // (간단히 _fireCount를 증가시키고 Render에서 AreaAttackVisuals를 처리할 수 있도록)
            _fireCount++;

            mouseWorldPos.y = originParent.position.y;
            transform.parent = null;
            transform.position = mouseWorldPos;

            // 데미지 처리는 서버에서 진행되어야 하므로 (예시로 추가해야 함)

            float scopeSize = WeaponSO.tileSize;
            attackScope.transform.localScale = new Vector3(scopeSize, scopeSize, scopeSize);
            yield return new WaitForSeconds(1f);
            attackScope.transform.localScale = Vector3.zero;
            float lifeTime = WeaponSO.projectileSpeed * .08f;
            VisualEffect.SetFloat("Size", WeaponSO.tileSize * 0.1f);
            VisualEffect.SetFloat("LifeTime", lifeTime);
            VisualEffect.Play();
            yield return new WaitForSeconds(lifeTime);
            VisualEffect.enabled = false;
            transform.parent = originParent;
            transform.localPosition = Vector3.zero;
            yield return null;
        }

        private IEnumerator FireLaser()
        {
            _fireCount++; // 로컬과 클라이언트 시각 동기화를 위해 증가

            if (LineRenderer != null)
            {
                LineRenderer.enabled = true;
                if (ParticleEffect != null)
                    ParticleEffect.Play();
                LineRenderer.positionCount = 2;
                LineRenderer.SetPosition(0, FireTransform.position);
                LineRenderer.SetPosition(1, FireTransform.position);

                Ray ray = new Ray(FireTransform.position, transform.forward);
                Vector3 endPoint;

                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    endPoint = hit.point;
                }
                else
                {
                    endPoint = FireTransform.position + transform.forward * 50;
                }

                float timer = 0f;
                float duration = .5f;
                Vector3 startPos = FireTransform.position;
                if (hit.collider.TryGetComponent<IDamageable>(out IDamageable damageableObject))
                {
                    damageableObject.TakeHit(damage + WeaponSO.weaponDamage, hit); // 데미지 입히기
                }

                while (timer < duration)
                {
                    timer += Time.deltaTime;
                    float progress = timer / duration;
                    LineRenderer.SetPosition(1, Vector3.Lerp(startPos, endPoint, progress));
                    yield return null;
                }

                LineRenderer.SetPosition(1, endPoint);

                yield return new WaitForSeconds(0.3f);
                if (ParticleEffect != null)
                    ParticleEffect.Stop();
                LineRenderer.enabled = false;
            }
            else if (VisualEffect != null)
            {
                VisualEffect.Play();
                if (ParticleEffect != null)
                    ParticleEffect.Play();

                Ray ray = new Ray(FireTransform.position, transform.forward);
                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, hit.distance * 0.5f, 0));
                }
                else
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, 50, 0));
                }

                yield return new WaitForSeconds(0.3f);
                VisualEffect.Stop();
                if (ParticleEffect != null)
                    ParticleEffect.Stop();
            }
        }

        // ---  Visual Only Coroutines (Render 계층에서 호출) ---
        private IEnumerator AreaAttackVisuals()
        {
            // StateAuthority(발사자)는 기존 코루틴에서 처리되므로 중복 실행 방지
            if (HasStateAuthority) yield break;

            float scopeSize = WeaponSO.tileSize;
            attackScope.transform.localScale = new Vector3(scopeSize, scopeSize, scopeSize);
            yield return new WaitForSeconds(1f);
            attackScope.transform.localScale = Vector3.zero;

            float lifeTime = WeaponSO.projectileSpeed * .08f;
            VisualEffect.SetFloat("Size", WeaponSO.tileSize * 0.1f);
            VisualEffect.SetFloat("LifeTime", lifeTime);
            VisualEffect.Play();
            yield return new WaitForSeconds(lifeTime);
            VisualEffect.enabled = false;
        }

        private IEnumerator FireLaserVisuals()
        {
            if (HasStateAuthority) yield break;

            if (LineRenderer != null)
            {
                LineRenderer.enabled = true;
                if (ParticleEffect != null) ParticleEffect.Play();

                LineRenderer.positionCount = 2;
                LineRenderer.SetPosition(0, FireTransform.position);

                // 단순화된 엔드포인트 계산 (클라이언트는 데미지를 주지 않음)
                Ray ray = new Ray(FireTransform.position, transform.forward);
                Vector3 endPoint = Physics.Raycast(ray, out RaycastHit hit) 
                    ? hit.point 
                    : FireTransform.position + transform.forward * 50;

                float timer = 0f;
                float duration = .5f;
                Vector3 startPos = FireTransform.position;

                while (timer < duration)
                {
                    timer += Time.deltaTime;
                    float progress = timer / duration;
                    LineRenderer.SetPosition(1, Vector3.Lerp(startPos, endPoint, progress));
                    yield return null;
                }

                LineRenderer.SetPosition(1, endPoint);

                yield return new WaitForSeconds(0.3f);
                if (ParticleEffect != null) ParticleEffect.Stop();
                LineRenderer.enabled = false;
            }
            else if (VisualEffect != null)
            {
                VisualEffect.Play();
                if (ParticleEffect != null) ParticleEffect.Play();

                Ray ray = new Ray(FireTransform.position, transform.forward);
                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, hit.distance * 0.5f, 0));
                }
                else
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, 50, 0));
                }

                yield return new WaitForSeconds(0.3f);
                VisualEffect.Stop();
                if (ParticleEffect != null) ParticleEffect.Stop();
            }
        }
    }
}

using System.Collections;
using Fusion;
using UnityEngine;

namespace Projectiles.NetworkObjectExample
{
    public class Weapon_NetworkObject : WeaponBase
    {
        // PRIVATE MEMBERS

        [SerializeField] private PhysicsProjectile _projectilePrefab;

        [SerializeField,
         Tooltip(
             "NetworkObjectBuffer will pre-spawn projectiles in advance to mitigate spawn delay on input authority")]
        private bool _useBuffer;

        [SerializeField] private NetworkObjectBuffer _projectileBuffer;

        [Networked] private int _fireCount { get; set; }

        public WeaponScriptableObject WeaponSO;

        private int _visibleFireCount;

        private Transform originParent;

        private float damage;
        private float criticalDamage;
        public LayerMask raycastLayerMask;

        private bool _isBoundToOwner;

        // WeaponBase INTERFACE

        public override void Fire(float damage, float criticalDamage)
        {
            this.damage = damage;
            this.criticalDamage = criticalDamage;
            switch (WeaponSO.weaponType)
            {
                case WeaponType.Projectile:
                    if (_useBuffer == true)
                    {
                        FireWithBuffer();
                    }
                    else
                    {
                        FireSimple();
                    }

                    _fireCount++;
                    break;
                case WeaponType.Laser:
                    StartCoroutine(FireLaser());
                    break;
                case WeaponType.Area:
                    StartCoroutine(AreaAttack());
                    break;
                case WeaponType.Strike:
                    break;
            }
        }

        public override void Spawned()
        {
            // In case of late join (and other scenarios) this object can be spawned
            // with fire count larger than zero. To prevent unwanted fire effects triggered in Render method
            // we consider all fire that happened before the Spawn as already visible.
            _visibleFireCount = _fireCount;
            originParent = transform.parent;
            _isBoundToOwner = BindToOwnerWeaponHold();
        }

        public override void FixedUpdateNetwork()
        {
            if (_isBoundToOwner == false)
            {
                _isBoundToOwner = BindToOwnerWeaponHold();
            }
        }

        private bool BindToOwnerWeaponHold()
        {
            if (Runner == null || Object == null)
                return false;

            if (Runner.TryGetPlayerObject(Object.InputAuthority, out NetworkObject ownerObject) == false)
            {
                // In case the player object is not set via SetPlayerObject, try to find it by checking if parent was set by authority
                // Or maybe fall back. But assuming TryGetPlayerObject works (as used in GameManager).
                return false;
            }

            WeaponController weaponController = ownerObject.GetComponent<WeaponController>();
            if (weaponController == null || weaponController.weaponHold == null)
                return false;

            transform.SetParent(weaponController.weaponHold, false);
            transform.localPosition = Vector3.zero;
            transform.localRotation = Quaternion.identity;
            originParent = transform.parent; // Update originParent after binding
            return true;
        }

        public override void Render()
        {
            if (_visibleFireCount < _fireCount)
            {
                // WeaponSO null 체크 추가
                if (WeaponSO != null)
                {
                    // PlayFireEffect(); // 사운드 재생
                    switch (WeaponSO.weaponType)
                    {
                        case WeaponType.Laser:
                            StartCoroutine(FireLaserVisuals());
                            break;
                        case WeaponType.Area:
                            StartCoroutine(AreaAttackVisuals());
                            break;
                        case WeaponType.Projectile:
                            break;
                    }
                }
            }

            _visibleFireCount = _fireCount;
        }

        // PRIVATE METHODS

        private void FireSimple()
        {
            // Spawn can be called only on state authority
            if (HasStateAuthority == false)
                return;

            var projectile = Runner.Spawn(_projectilePrefab, FireTransform.position, FireTransform.rotation,
                Object.InputAuthority);
            projectile.Fire(FireTransform.position, FireTransform.rotation, damage + WeaponSO.weaponDamage, raycastLayerMask);
        }

        private void FireWithBuffer()
        {
            // In Fusion 2 there is no longer a predicted spawn. We can go around this to have a buffer of pre-spawned
            // objects that are already living inside simulation but inactive. Check NetworkObjectBuffer component for more info.
            var projectile = _projectileBuffer.Get<PhysicsProjectile>(FireTransform.position, FireTransform.rotation,
                Object.InputAuthority);
            if (projectile != null)
            {
                projectile.Fire(FireTransform.position, FireTransform.rotation, damage + WeaponSO.weaponDamage, raycastLayerMask);
            }
        }

        private IEnumerator AreaAttack()
        {
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            Plane groundPlane = new Plane(Vector3.up, transform.root.position);
            Vector3 mouseWorldPos = Vector3.zero;
            if (groundPlane.Raycast(ray, out float distance))
            {
                mouseWorldPos = ray.GetPoint(distance);
            }

            //  네트워크 버퍼에 타겟 위치 저장 (Laser/Area 동기화를 위해)
            // (간단히 _fireCount를 증가시키고 Render에서 AreaAttackVisuals를 처리할 수 있도록)
            _fireCount++;

            mouseWorldPos.y = originParent.position.y;
            transform.parent = null;
            transform.position = mouseWorldPos;

            // 데미지 처리는 서버에서 진행되어야 하므로 (예시로 추가해야 함)

            float scopeSize = WeaponSO.tileSize;
            attackScope.transform.localScale = new Vector3(scopeSize, scopeSize, scopeSize);
            yield return new WaitForSeconds(1f);
            attackScope.transform.localScale = Vector3.zero;
            float lifeTime = WeaponSO.projectileSpeed * .08f;
            VisualEffect.SetFloat("Size", WeaponSO.tileSize * 0.1f);
            VisualEffect.SetFloat("LifeTime", lifeTime);
            VisualEffect.Play();
            yield return new WaitForSeconds(lifeTime);
            VisualEffect.enabled = false;
            transform.parent = originParent;
            transform.localPosition = Vector3.zero;
            yield return null;
        }

        private IEnumerator FireLaser()
        {
            _fireCount++; // 로컬과 클라이언트 시각 동기화를 위해 증가

            if (LineRenderer != null)
            {
                LineRenderer.enabled = true;
                if (ParticleEffect != null)
                    ParticleEffect.Play();
                LineRenderer.positionCount = 2;
                LineRenderer.SetPosition(0, FireTransform.position);
                LineRenderer.SetPosition(1, FireTransform.position);

                Ray ray = new Ray(FireTransform.position, transform.forward);
                Vector3 endPoint;

                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    endPoint = hit.point;
                }
                else
                {
                    endPoint = FireTransform.position + transform.forward * 50;
                }

                float timer = 0f;
                float duration = .5f;
                Vector3 startPos = FireTransform.position;
                if (hit.collider.TryGetComponent<IDamageable>(out IDamageable damageableObject))
                {
                    damageableObject.TakeHit(damage + WeaponSO.weaponDamage, hit); // 데미지 입히기
                }

                while (timer < duration)
                {
                    timer += Time.deltaTime;
                    float progress = timer / duration;
                    LineRenderer.SetPosition(1, Vector3.Lerp(startPos, endPoint, progress));
                    yield return null;
                }

                LineRenderer.SetPosition(1, endPoint);

                yield return new WaitForSeconds(0.3f);
                if (ParticleEffect != null)
                    ParticleEffect.Stop();
                LineRenderer.enabled = false;
            }
            else if (VisualEffect != null)
            {
                VisualEffect.Play();
                if (ParticleEffect != null)
                    ParticleEffect.Play();

                Ray ray = new Ray(FireTransform.position, transform.forward);
                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, hit.distance * 0.5f, 0));
                }
                else
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, 50, 0));
                }

                yield return new WaitForSeconds(0.3f);
                VisualEffect.Stop();
                if (ParticleEffect != null)
                    ParticleEffect.Stop();
            }
        }

        // ---  Visual Only Coroutines (Render 계층에서 호출) ---
        private IEnumerator AreaAttackVisuals()
        {
            // StateAuthority(발사자)는 기존 코루틴에서 처리되므로 중복 실행 방지
            if (HasStateAuthority) yield break;

            float scopeSize = WeaponSO.tileSize;
            attackScope.transform.localScale = new Vector3(scopeSize, scopeSize, scopeSize);
            yield return new WaitForSeconds(1f);
            attackScope.transform.localScale = Vector3.zero;

            float lifeTime = WeaponSO.projectileSpeed * .08f;
            VisualEffect.SetFloat("Size", WeaponSO.tileSize * 0.1f);
            VisualEffect.SetFloat("LifeTime", lifeTime);
            VisualEffect.Play();
            yield return new WaitForSeconds(lifeTime);
            VisualEffect.enabled = false;
        }

        private IEnumerator FireLaserVisuals()
        {
            if (HasStateAuthority) yield break;

            if (LineRenderer != null)
            {
                LineRenderer.enabled = true;
                if (ParticleEffect != null) ParticleEffect.Play();

                LineRenderer.positionCount = 2;
                LineRenderer.SetPosition(0, FireTransform.position);

                // 단순화된 엔드포인트 계산 (클라이언트는 데미지를 주지 않음)
                Ray ray = new Ray(FireTransform.position, transform.forward);
                Vector3 endPoint = Physics.Raycast(ray, out RaycastHit hit) 
                    ? hit.point 
                    : FireTransform.position + transform.forward * 50;

                float timer = 0f;
                float duration = .5f;
                Vector3 startPos = FireTransform.position;

                while (timer < duration)
                {
                    timer += Time.deltaTime;
                    float progress = timer / duration;
                    LineRenderer.SetPosition(1, Vector3.Lerp(startPos, endPoint, progress));
                    yield return null;
                }

                LineRenderer.SetPosition(1, endPoint);

                yield return new WaitForSeconds(0.3f);
                if (ParticleEffect != null) ParticleEffect.Stop();
                LineRenderer.enabled = false;
            }
            else if (VisualEffect != null)
            {
                VisualEffect.Play();
                if (ParticleEffect != null) ParticleEffect.Play();

                Ray ray = new Ray(FireTransform.position, transform.forward);
                if (Physics.Raycast(ray, out RaycastHit hit))
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, hit.distance * 0.5f, 0));
                }
                else
                {
                    VisualEffect.SetVector3("TargetPosition", new Vector3(0, 50, 0));
                }

                yield return new WaitForSeconds(0.3f);
                VisualEffect.Stop();
                if (ParticleEffect != null) ParticleEffect.Stop();
            }
        }
    }
}
